const adminPlacesByIDs = `-- name: AdminPlacesByIDs :many
SELECT p.geoname_id,
       coalesce(pn.name, pd.name, p.name)::text AS name,
       coalesce(an.name, ad.name, a.ascii_name, '')::text AS region_name,
       p.population
FROM geonames_places p
LEFT JOIN countries co ON co.code = p.country_code
LEFT JOIN geonames_place_names pn ON pn.geoname_id = p.geoname_id AND pn.locale = $1::text
LEFT JOIN geonames_place_names pd ON pd.geoname_id = p.geoname_id AND pd.locale = co.default_locale
LEFT JOIN geonames_admin1 a ON a.country_code = p.country_code AND a.admin1_code = p.admin1_code
LEFT JOIN geonames_admin1_names an
       ON an.country_code = a.country_code AND an.admin1_code = a.admin1_code AND an.locale = $1::text
LEFT JOIN geonames_admin1_names ad
       ON ad.country_code = a.country_code AND ad.admin1_code = a.admin1_code AND ad.locale = co.default_locale
WHERE p.geoname_id = ANY ($2::bigint[])
`

type AdminPlacesByIDsParams struct {
	Locale string
	Ids    []int64
}

type AdminPlacesByIDsRow struct {
	GeonameID  int64
	Name       string
	RegionName string
	Population int64
}

// Места-кандидаты отчёта сверки: название и регион на языке ответа (иначе язык страны источника, затем
// name/ascii_name источника), население. Пропавших из таблицы мест (удалены следующим импортом) нет в ответе.
func (q *Queries) AdminPlacesByIDs(ctx context.Context, arg AdminPlacesByIDsParams) ([]AdminPlacesByIDsRow, error) {
	rows, err := q.db.Query(ctx, adminPlacesByIDs, arg.Locale, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AdminPlacesByIDsRow
	for rows.Next() {
		var i AdminPlacesByIDsRow
		if err := rows.Scan(
			&i.GeonameID,
			&i.Name,
			&i.RegionName,
			&i.Population,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

